def main():
    payload=base64.b64decode(''.join(PAYLOAD.split()))
    if hashlib.sha256(payload).hexdigest() != EXPECTED_DIGEST:
        raise SystemExit('Integrity check failed; no files changed')
    with tarfile.open(fileobj=io.BytesIO(lzma.decompress(payload)),mode='r:') as tar:
        for member in tar.getmembers():
            relative=Path(member.name)
            if relative.is_absolute() or '..' in relative.parts or not member.isfile():
                raise SystemExit(f'Unsafe path: {member.name}')
            data=tar.extractfile(member).read()
            relative.parent.mkdir(parents=True,exist_ok=True)
            relative.write_bytes(data)
            print(f'Upgraded {relative}')
    print('Kārya 2.1 source overlay applied. Run flutter pub get, flutter analyze, flutter test and flutter build apk.')

if __name__ == '__main__':
    main()